head.b:skin:
/* ==========================================================================
   THEME BLOGGER: ĐẠO TÂM (ĐỌC TRUYỆN CHỮ & AUDIO)
   Phong cách sang trọng Gold & Dark (tương tự dammythuquan.com)
   - Dark / Light Mode
   - Mục lục chương chi tiết
   - Máy nghe Audio & Giọng đọc tự động
   - Tuyệt đối KHÔNG có phần đề xuất truyện
   - Lưu tiến trình đọc theo tài khoản người dùng
   ========================================================================== */

:root {
  --bg-main: #0d0e12;
  --bg-header: rgba(18, 19, 24, 0.95);
  --bg-card: #16171d;
  --bg-card-hover: #1f2029;
  --bg-input: #1a1b22;
  --bg-modal: #16171d;
  --border-color: #262833;
  --border-gold: rgba(234, 179, 8, 0.35);
  --text-primary: #f3f4f6;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --accent-gold: #f59e0b;
  --accent-gold-light: #fbbf24;
  --accent-gold-dark: #d97706;
  --accent-glow: 0 0 20px rgba(245, 158, 11, 0.25);
  --badge-hot: #ef4444;
  --badge-full: #10b981;
  --font-heading: 'Cinzel', 'Playfair Display', serif;
  --font-body: 'Be Vietnam Pro', sans-serif;
  --reader-font: 'Lora', serif;
  --reader-size: 19px;
  --reader-line: 1.85;
  --transition: all 0.25s ease;
}

[data-theme='light'] {
  --bg-main: #f8f9fc;
  --bg-header: rgba(255, 255, 255, 0.96);
  --bg-card: #ffffff;
  --bg-card-hover: #f1f3f9;
  --bg-input: #edf0f7;
  --bg-modal: #ffffff;
  --border-color: #e2e8f0;
  --border-gold: rgba(217, 119, 6, 0.4);
  --text-primary: #1e293b;
  --text-secondary: #475569;
  --text-muted: #94a3b8;
  --accent-gold: #d97706;
  --accent-gold-light: #f59e0b;
  --accent-gold-dark: #b45309;
  --accent-glow: 0 0 15px rgba(217, 119, 6, 0.15);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background-color: var(--bg-main);
  color: var(--text-primary);
  font-family: var(--font-body);
  line-height: 1.6;
  min-height: 100vh;
  transition: background-color 0.3s ease, color 0.3s ease;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}

.dmc-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg-header);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-gold);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

.dmc-nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  gap: 16px;
}

.dmc-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 800;
  background: linear-gradient(135deg, #fef08a 0%, #f59e0b 50%, #d97706 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 10px rgba(245, 158, 11, 0.2);
  white-space: nowrap;
}

.dmc-brand i {
  -webkit-text-fill-color: initial;
  color: var(--accent-gold);
  font-size: 22px;
}

.dmc-menu {
  display: flex;
  align-items: center;
  list-style: none;
  gap: 6px;
}

.dmc-menu-item a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 14px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
}

.dmc-menu-item a:hover,
.dmc-menu-item.active a {
  color: var(--accent-gold-light);
  background: rgba(245, 158, 11, 0.1);
}

.dmc-search-box {
  flex: 1;
  max-width: 380px;
  position: relative;
  display: flex;
  align-items: center;
}

.dmc-search-input {
  width: 100%;
  height: 40px;
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 20px;
  padding: 0 75px 0 16px;
  color: var(--text-primary);
  font-size: 13.5px;
  outline: none;
}

.dmc-search-input:focus {
  border-color: var(--accent-gold);
  box-shadow: 0 0 10px rgba(245, 158, 11, 0.2);
}

.dmc-search-btn {
  position: absolute;
  right: 4px;
  top: 4px;
  height: 32px;
  padding: 0 16px;
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-gold-dark));
  border: none;
  border-radius: 16px;
  color: #000;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
}

.dmc-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.dmc-btn-icon {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.dmc-btn-icon:hover {
  border-color: var(--accent-gold);
  color: var(--accent-gold);
}

.dmc-btn-auth {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 16px;
  background: linear-gradient(135deg, #1e2029, #2b2e3c);
  border: 1px solid var(--border-gold);
  border-radius: 20px;
  color: var(--accent-gold-light);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.dmc-btn-auth:hover {
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-gold-dark));
  color: #000;
}

.dmc-audio-bar {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 90%;
  max-width: 820px;
  background: var(--bg-card);
  border: 1px solid var(--border-gold);
  border-radius: 18px;
  box-shadow: 0 12px 35px rgba(0, 0, 0, 0.5);
  padding: 12px 20px;
  z-index: 99;
  display: none;
  align-items: center;
  gap: 16px;
}

.dmc-audio-bar.show {
  display: flex;
}

.audio-info {
  flex: 1;
  min-width: 140px;
}

.audio-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--accent-gold-light);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.audio-sub {
  font-size: 11.5px;
  color: var(--text-muted);
}

.audio-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.audio-btn {
  background: transparent;
  border: none;
  color: var(--text-primary);
  font-size: 16px;
  cursor: pointer;
}

.audio-btn-play {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--accent-gold), var(--accent-gold-dark));
  border-radius: 50%;
  color: #000;
}

.audio-timeline-wrap {
  flex: 2;
  display: flex;
  align-items: center;
  gap: 8px;
}

.audio-slider {
  flex: 1;
  accent-color: var(--accent-gold);
  cursor: pointer;
}

.audio-time {
  font-size: 11px;
  color: var(--text-muted);
  font-family: monospace;
}

.audio-speed {
  background: var(--bg-input);
  border: 1px solid var(--border-color);
  color: var(--accent-gold);
  font-size: 12px;
  padding: 3px 8px;
  border-radius: 6px;
}

.dmc-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 32px 0 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.dmc-section-title {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 700;
  color: var(--accent-gold-light);
  display: flex;
  align-items: center;
  gap: 10px;
  text-transform: uppercase;
}

.dmc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 20px;
  margin-bottom: 40px;
}

.novel-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.novel-card:hover {
  transform: translateY(-5px);
  border-color: var(--accent-gold);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4), 0 0 12px rgba(245, 158, 11, 0.2);
}

.novel-thumb-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  background: #111;
}

.novel-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.badge-full {
  position: absolute;
  top: 8px;
  left: 8px;
  background: var(--badge-full);
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 4px;
}

.badge-hot {
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--badge-hot);
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 4px;
}

.novel-overlay-stats {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px 8px 8px;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.95), transparent);
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #e5e7eb;
}

.novel-info {
  padding: 12px;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.novel-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 6px;
}

.novel-meta-tags {
  font-size: 11.5px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 8px;
}

.reader-container {
  max-width: 900px;
  margin: 30px auto 60px;
  padding: 0 16px;
}

.reader-nav-top {
  position: sticky;
  top: 76px;
  z-index: 50;
  background: var(--bg-card);
  border: 1px solid var(--border-gold);
  border-radius: 12px;
  padding: 10px 16px;
  margin-bottom: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.reader-chapter-title {
  font-family: var(--font-heading);
  font-size: 24px;
  color: var(--accent-gold-light);
  text-align: center;
  margin: 28px 0 10px;
}

.reader-content {
  font-family: var(--reader-font);
  font-size: var(--reader-size);
  line-height: var(--reader-line);
  color: var(--text-primary);
  text-align: justify;
}

.reader-content p {
  margin-bottom: 1.4em;
  text-indent: 1.2em;
}

.reader-scroll-progress {
  position: fixed;
  top: 72px;
  left: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-gold), var(--accent-gold-light));
  z-index: 101;
  width: 0%;
}

.dmc-toc-container {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 24px;
  margin-bottom: 40px;
}

.toc-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.toc-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 10px;
  max-height: 540px;
  overflow-y: auto;
}

.toc-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--bg-input);
  border-radius: 8px;
  font-size: 13.5px;
}

.dmc-footer {
  background: #090a0d;
  border-top: 1px solid var(--border-gold);
  padding: 40px 0 25px;
  margin-top: 60px;
  font-size: 13.5px;
  color: var(--text-muted);
}
